def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Skip leading comma (field separator)
        if i > 0 and line[i] == ',':
            i += 1
            if i == len(line):
                # Trailing comma means empty field at end
                fields.append('')
                break

        if i == len(line):
            break

        # Check if field is quoted
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ''
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote represents one quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # After closing quote, must have comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(field)
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = ''
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain quotes
                    return None
                field += line[i]
                i += 1
            fields.append(field)

    # Handle the case of an empty line
    if len(fields) == 0:
        fields.append('')

    return fields

